{%- from "adeel_traders/templates/print/base_a4.html" import styles, title_block, signatures -%}
{#- Blind count: while a count is open, only people who may post it see system quantities. -#}
{%- set blind = doc.docstatus == 0 and not can("stock.count.post") -%}
{%- set cost = can("cost.view") and not blind -%}
{{ letter_head or "" }}
{{ styles() }}
<div class="at-doc">
{{ title_block("Stock count", doc.name, [
	("Location", doc.warehouse.rsplit(" - ", 1)[0]),
	("Date", frappe.format(doc.posting_date, {"fieldtype": "Date"})),
	("Status", "Posted" if doc.docstatus == 1 else "Cancelled" if doc.docstatus == 2 else "Open"),
	("Lines", doc["items"] | length),
]) }}
<table class="at-table">
	<thead><tr>
		<th style="width:4%">#</th><th>Product</th><th>Code</th><th>Batch</th>
		<th class="num">Counted</th>
		{% if not blind %}<th class="num">System</th><th class="num">Difference</th>{% endif %}
		{% if cost %}<th class="num">Value</th>{% endif %}
	</tr></thead>
	<tbody>
	{%- for row in doc["items"] %}
	<tr>
		<td class="at-muted">{{ loop.index }}</td>
		<td>{{ row.item_name }}{% if row.not_scanned %} <span class="at-muted">(not scanned)</span>{% endif %}</td>
		<td class="at-muted">{{ row.item_code }}</td>
		<td class="at-muted">{{ row.batch_no or "" }}</td>
		<td class="num">{{ frappe.utils.fmt_money(row.counted_qty, precision=0) }}</td>
		{% if not blind %}
		<td class="num">{{ frappe.utils.fmt_money(row.system_qty, precision=0) }}</td>
		<td class="num">{{ ("+" if row.difference > 0 else "") ~ frappe.utils.fmt_money(row.difference, precision=0) }}</td>
		{% endif %}
		{% if cost %}<td class="num">Rs {{ frappe.utils.fmt_money(row.difference_value, precision=0) }}</td>{% endif %}
	</tr>
	{%- endfor %}
	{#- products with stock here that nobody scanned, counted as zero (open counts, not blind) -#}
	{%- if not blind %}{% for m in doc.unscanned() %}
	<tr>
		<td class="at-muted">{{ doc["items"] | length + loop.index }}</td>
		<td>{{ m.item_name }} <span class="at-muted">(not scanned, counted as zero)</span></td>
		<td class="at-muted">{{ m.item_code }}</td><td></td>
		<td class="num">0</td>
		<td class="num">{{ frappe.utils.fmt_money(m.system, precision=0) }}</td>
		<td class="num">{{ frappe.utils.fmt_money(m.difference, precision=0) }}</td>
		{% if cost %}<td class="num">Rs {{ frappe.utils.fmt_money(m.difference_value, precision=0) }}</td>{% endif %}
	</tr>
	{%- endfor %}{% endif %}
	</tbody>
	<tfoot><tr>
		<td></td><td colspan="3">Total</td>
		<td class="num">{{ frappe.utils.fmt_money(doc.total_counted, precision=0) }}</td>
		{% if not blind %}<td></td><td class="num">{{ ("+" if doc.total_difference > 0 else "") ~ frappe.utils.fmt_money(doc.total_difference, precision=0) }}</td>{% endif %}
		{% if cost %}<td class="num">Rs {{ frappe.utils.fmt_money(doc.difference_value, precision=0) }}</td>{% endif %}
	</tr></tfoot>
</table>
{% if blind %}<div class="at-note">Open count: system quantities are shown to the manager when it is posted.</div>{% endif %}
{{ signatures(["Counted by", "Checked by", "Posted by"]) }}
</div>
